(function(){"use strict";if(typeof gsap==="undefined"||typeof ScrollTrigger==="undefined")return;const prefersReduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(prefersReduced)return;function initPageOverlay(){let overlay=document.getElementById("sk-page-overlay");if(!overlay){overlay=document.createElement("div");overlay.id="sk-page-overlay";overlay.setAttribute("aria-hidden","true");document.body.prepend(overlay)}gsap.fromTo(overlay,{opacity:1},{opacity:0,duration:.85,ease:"power2.out",delay:.08,onStart(){overlay.style.pointerEvents="all"},onComplete(){overlay.style.pointerEvents="none"}});if(!window.skPageOverlayClickBound){window.skPageOverlayClickBound=true;document.addEventListener("click",e=>{const a=e.target.closest("a[href]");if(!a)return;const raw=a.getAttribute("href")||"";if(!raw||raw.startsWith("#")||raw.includes("/#")||raw.startsWith("?"))return;if(a.target==="_blank")return;if(/^(mailto:|tel:|javascript:|data:)/i.test(raw))return;if(a.hasAttribute("download"))return;let url;try{url=new URL(raw,location.href)}catch{return}if(url.origin!==location.origin)return;if(/^\/(wp-admin|wp-login)/i.test(url.pathname))return;e.preventDefault();const dest=url.href;if(typeof window.skLenisPause==="function")window.skLenisPause();overlay.style.pointerEvents="all";gsap.fromTo(overlay,{opacity:0},{opacity:1,duration:.5,ease:"power2.in",onComplete(){window.location.href=dest}})})}}function initCurtainLines(){const selectors=".av16-heading";gsap.utils.toArray(selectors).forEach(el=>{if(el.dataset.skCurtain)return;el.dataset.skCurtain="1";const existingLine=el.nextElementSibling;if(existingLine&&existingLine.classList.contains("sk-heading-curtain-line")){existingLine.remove()}const line=document.createElement("span");line.className="sk-heading-curtain-line";line.setAttribute("aria-hidden","true");el.insertAdjacentElement("afterend",line);gsap.set(line,{scaleX:0,opacity:0,transformOrigin:"left center"});gsap.to(line,{scaleX:1,opacity:1,duration:1.3,ease:"power4.inOut",delay:.22,scrollTrigger:{trigger:el,start:"top 88%",toggleActions:"play none none none"}})})}function initSectionPulse(){let bar=document.getElementById("sk-section-pulse");if(!bar){bar=document.createElement("div");bar.id="sk-section-pulse";bar.setAttribute("aria-hidden","true");document.body.appendChild(bar)}const map=[{sel:".hero--fullscreen, .hero--split",col:"rgba(212,175,106,0.55)"},{sel:".about-section",col:"rgba(196,144,42,0.70)"},{sel:".sk-rc-section",col:"rgba(184,98,63,0.70)"},{sel:".strip--circular",col:"rgba(228,189,160,0.70)"},{sel:".founders-section",col:"rgba(196,144,42,0.72)"},{sel:".sk-stories-preview-section",col:"rgba(184,98,63,0.70)"},{sel:".faq-section",col:"rgba(122,149,121,0.70)"},{sel:".cta-section, .sk-cta-section",col:"rgba(212,175,106,0.80)"}];map.forEach(({sel:sel,col:col})=>{const el=document.querySelector(sel);if(!el)return;ScrollTrigger.create({trigger:el,start:"top 55%",end:"bottom 45%",onEnter(){gsap.to(bar,{backgroundColor:col,opacity:.8,duration:.65,ease:"power2.inOut"})},onLeave(){gsap.to(bar,{opacity:.22,duration:.5,ease:"power2.out"})},onEnterBack(){gsap.to(bar,{backgroundColor:col,opacity:.8,duration:.65,ease:"power2.inOut"})},onLeaveBack(){gsap.to(bar,{opacity:.22,duration:.5,ease:"power2.out"})}})})}function init(){initPageOverlay();initCurtainLines();initSectionPulse();document.fonts.ready.then(()=>{setTimeout(()=>ScrollTrigger.refresh(),150)})}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();